<template><div><h1>Register</h1><AppInput v-model="email" placeholder="Email"/><AppInput v-model="name" placeholder="Name"/><AppInput v-model="password" type="password" placeholder="Password"/><AppButton @click="submit">Create account</AppButton></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';import AppInput from '../components/AppInput.vue';import AppButton from '../components/AppButton.vue';const email=ref('');const password=ref('');const name=ref('');const auth=useAuthStore();const router=useRouter();const submit=async()=>{await auth.register({email:email.value,password:password.value,name:name.value});router.push('/');};</script>
